// English: the source catalogue. Every key lives here first; other locales
// translate some or all of them (see docs/design-system.md, "i18n").
//
// Keys are `area.thing.part`. A plural message is an object of Intl.PluralRules
// forms (`one`, `few`, `other`, …) picked by `{count}`, with an optional `zero`.
// Only Foreman's own words go here: never task titles, chat text or file names.
