  // ---- The welcome tour (Help → Welcome tour, the rail's ? button). {key}, {picker}, {commit}, {pr}, {fix}, {palette} and {shortcuts} are shortcuts shown as keycaps; {step} and {total} are numbers. ----
  'tour.label': 'Welcome tour',
  'tour.paletteDetail': 'A short walk past the main controls',
  'tour.settings.help': 'A short walk past Foreman’s main controls.',
  'tour.settings.show': 'Show the tour',
