  'tour.action.automations': 'Open Automations',
  'tour.action.assistant': 'Open the assistant',
  'tour.action.accessibility': 'Open Settings → Accessibility',
  'tour.step.welcome.title': 'Welcome to Foreman',
  'tour.step.welcome.body': 'Run coding agents in parallel, each on its own branch in its own copy of your repository. Everything stays on this computer. Here’s where things are.',
  'tour.step.addRepo.title': 'Add a repository',
  'tour.step.addRepo.body': 'Open a folder that’s already a git repository, clone one from GitHub, or use Quick start to make a new one. Right-click a repository for its settings: setup script, run script and checks.',
  'tour.step.addRepo.where': 'the + button in the strip of repository icons',
  'tour.step.newWorkspace.title': 'Start a workspace',
  'tour.step.newWorkspace.body': 'Each workspace is a new branch in its own worktree, with its own ports and terminal, so agents never collide. Press {key}, then describe the task; images work too.',
  'tour.step.newWorkspace.where': 'the New workspace button near the top',
  'tour.step.needsYou.title': 'Needs you',
  'tour.step.needsYou.body': 'With several agents running, you stop watching them. Anything waiting on you (an approval, a question, a plan, a failed turn) is collected here and on Home, with a count, a notification and a tray or menu-bar badge. {next} jumps to the next workspace that needs you; {jump} to what needs you in the chat you’re in.',
  'tour.step.needsYou.where': 'the All, Needs you, Running and Pinned filters',
  'tour.step.layout.title': 'Two ways to see your work',
  'tour.step.layout.body': 'Three panes shows one workspace with its changes and terminal beside it; that’s what you have now. Tiles shows several workspaces’ chats side by side. Switch any time with {palette} (“Switch to tiles”) or in Settings → Appearance → Window layout.',
  'tour.step.automations.title': 'Templates and Automations',
  'tour.step.automations.body': 'Templates are prompts with blanks for the details; keep your own, or the repository’s. Automations run a template on a schedule (daily, weekly and so on) while Foreman is open, with a calendar of what ran and what’s next.',
  'tour.step.automations.where': 'Automations, at the top of the sidebar',
  'tour.step.assistant.title': 'Ask the assistant',
  'tour.step.assistant.body': 'Not sure where something is? Ask here ({key}). It points you to the exact setting and never changes anything. It runs on Claude, so sign in to Claude first.',
  'tour.step.assistant.where': 'Assistant, under Automations',
  'tour.step.settings.title': 'Settings',
  'tour.step.settings.body': 'Accessibility: text size, zoom, color modes and screen-reader announcements. Agents: sign in and choose your default. MCP: repository servers are approved in a workspace’s Git panel, and agents get Foreman’s own tools. Remote workspaces (experimental, off by default) run a workspace in a cloud sandbox.',
  'tour.step.settings.where': 'the gear in the strip of repository icons',
  'tour.step.help.title': 'Find your way back',
  'tour.step.help.body': 'Replay this tour from here. Everything else is a search away: {palette} opens the command palette and {shortcuts} lists every shortcut.',
  'tour.step.help.where': 'the ? in the strip of repository icons',

